import{_ as o,o as e,c as t,a5 as r}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"Konado 설치","description":"","frontmatter":{"title":"Konado 설치","order":1},"headers":[],"relativePath":"ko/2.4/tutorial/install.md","filePath":"ko/2.4/tutorial/install.md","lastUpdated":1788455378000}'),l={name:"ko/2.4/tutorial/install.md"};function i(n,a,d,s,h,c){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="konado-설치" tabindex="-1">Konado 설치 <a class="header-anchor" href="#konado-설치" aria-label="Permalink to &quot;Konado 설치&quot;">​</a></h1><h2 id="필요-환경" tabindex="-1">필요 환경 <a class="header-anchor" href="#필요-환경" aria-label="Permalink to &quot;필요 환경&quot;">​</a></h2><p><strong>Godot 4.6 이상</strong>이 필요합니다.</p><p>다음 Godot 버전은 개발자가 테스트했으며 정상적으로 사용할 수 있습니다.</p><ul><li>4.6</li><li>4.5.1</li><li>4.5</li></ul><h3 id="플러그인-다운로드" tabindex="-1">플러그인 다운로드 <a class="header-anchor" href="#플러그인-다운로드" aria-label="Permalink to &quot;플러그인 다운로드&quot;">​</a></h3><h4 id="안정-버전-권장" tabindex="-1">안정 버전(권장) <a class="header-anchor" href="#안정-버전-권장" aria-label="Permalink to &quot;안정 버전(권장)&quot;">​</a></h4><p><a href="https://github.com/godothub/konado/releases/latest" target="_blank" rel="noreferrer">Konado 최신 버전 페이지</a>에서 최신 안정 버전 플러그인 ZIP 패키지를 다운로드하세요. 안정 버전은 충분히 검증되어 안정성과 신뢰성이 더 높으므로 프로덕션 환경의 첫 번째 선택입니다.</p><p>중국 본토 사용자들의 다운로드 경험을 개선하기 위해 다음 최적화 링크를 통한 리소스 다운로드를 권장합니다: <a href="https://atomgit.com/godothub/konado/releases" target="_blank" rel="noreferrer">Release 링크</a>. 이 링크는 다운로드 속도 개선에 도움이 됩니다.</p><h4 id="데일리-빌드-체험-버전" tabindex="-1">데일리 빌드(체험 버전) <a class="header-anchor" href="#데일리-빌드-체험-버전" aria-label="Permalink to &quot;데일리 빌드(체험 버전)&quot;">​</a></h4><p>데일리 빌드도 함께 제공합니다. 최신 개발 기능을 체험하려면 <a href="https://github.com/godothub/konado/releases/" target="_blank" rel="noreferrer">Konado 전체 릴리스 페이지</a>로 이동해 제목에 <code>Konado Daily Build</code>가 표시된 버전을 찾아 다운로드하세요.</p><p>개발자이며 최신 개발 기능을 체험하고 싶다면 데일리 빌드를 다운로드하고, 사용 중 만난 문제를 Issues에 피드백해 주세요.</p><blockquote><p>Caution: 데일리 빌드는 최신 개발 기능을 체험하기 위한 용도입니다. 충분히 테스트되지 않은 새 기능을 포함하므로 수정되지 않은 Bug가 있을 수 있습니다. <strong>프로덕션 환경에서는 사용하지 마세요</strong>. 실제 요구에 따라 신중하게 선택해 주세요.</p></blockquote><h2 id="설치-단계" tabindex="-1">설치 단계 <a class="header-anchor" href="#설치-단계" aria-label="Permalink to &quot;설치 단계&quot;">​</a></h2><ol><li>Godot 프로젝트 디렉터리에 플러그인 폴더 <code>addons</code>를 새로 만듭니다</li><li>release의 플러그인 zip 패키지를 다운로드합니다</li><li><code>addons</code> 디렉터리에 압축을 풉니다</li><li>Godot 프로젝트 설정에서 플러그인을 활성화하고 현재 프로젝트를 다시 로드합니다</li></ol><blockquote><p>Tip: 처음 설치하고 플러그인을 활성화할 때 몇 가지 오류가 나타날 수 있습니다. 무시해도 되며, 프로젝트를 다시 로드하면 됩니다.</p></blockquote><h2 id="개발팀-메시지" tabindex="-1">개발팀 메시지 <a class="header-anchor" href="#개발팀-메시지" aria-label="Permalink to &quot;개발팀 메시지&quot;">​</a></h2><p>Konado 플러그인 설치가 완료되었습니다. 본격적으로 창작을 시작하기 전에 메시지 하나를 전하고 싶습니다.</p><blockquote><p>&quot;어떤 산업에서든 상상력에 약간의 지혜가 더해지면 그것은 무엇도 막을 수 없는 무기가 된다.&quot;</p><p>-- 필립 K. 딕(Philip K. Dick)<br><em>Minority Report</em> (1956)</p></blockquote><p>항상 상상력과 완성도를 향한 태도를 지니고, 창작의 길에서 더 많은 가능성을 탐색하길 바랍니다.</p>',20)])])}const b=o(l,[["render",i]]);export{u as __pageData,b as default};
